// supabase/functions/_shared/output-guard/cluster-embeddings.ts
//
// GENERATED by tools/guard-embeddings/gen.mjs — do not edit by hand.
//
// Why this exists (2026-10-30 release audit): Layer 2 used to embed all
// 15 cluster phrases with gte-small on the first call of every cold
// isolate. Inference counts against the Edge Function CPU budget, so
// Ask Leiko died with "CPU Time exceeded" (HTTP 546) on a cold start
// and the app showed "I'm not sure I can answer that one". With these
// vectors precomputed, a request embeds only the response text.
//
// Layer 2 uses these ONLY when `phrases` exactly matches
// DIAGNOSTIC_CLUSTER_PHRASES (same text, same order). If the cluster is
// edited and this file isn't regenerated, Layer 2 falls back to
// embedding at runtime — slower, never wrong.

export interface PrecomputedCluster {
  model: string;
  phrases: ReadonlyArray<string>;
  vectors: ReadonlyArray<ReadonlyArray<number>>;
}

export const PRECOMPUTED_CLUSTER: PrecomputedCluster | null = null;
